// Build regeneration context from the rejected post + the rejection reason.
// Reuses WF1's prompt-merge logic; runs in REGENERATION MODE (prepends rejection_feedback).
// When the image was approved (copy-only reject), reuse the kept image_concept so the
// image is preserved. Returns { system, user, component, regen_copy, regen_image, regen_video,
// post_id, image_concept, image_status, post_image_url, video_concept }.
const post = $('Get Post').first().json;
const body = $('Webhook (fb-regenerate)').first().json.body;
const component = body.component;
const promptItems = $('Get Prompts + Bank').all();
const byName = Object.fromEntries(promptItems.map(i => [i.json.name, i.json.body]));
const bank = $('Get Message Bank').first()?.json?.variables ?? {};

const regen_copy = component === 'copy' || component === 'both';
const regen_image = component === 'image' || component === 'both';
const regen_video = component === 'video';
const rejection_feedback = (body.reason_code || '') + ': ' + (body.reason_text || '');
const kept_image_concept = (post.image_status === 'approved') ? (post.image_concept || '') : '';

let user = (byName['generator'] || '')
  .replaceAll('{{style_guide}}', byName['style_guide'] || '')
  .replaceAll('{{message_bank}}', JSON.stringify(bank))
  .replaceAll('{{pillar}}', post.pillar || '')
  .replaceAll('{{archetype}}', post.archetype || '')
  .replaceAll('{{subtopic}}', '')
  // generator v2 also carries Strategist-brief + regeneration placeholders. Fill the regen
  // values we have, image-only / no-brief defaults for the rest, then strip any leftover
  // placeholder token so a literal one never reaches the model.
  .replaceAll('{{rejection_feedback}}', rejection_feedback)
  .replaceAll('{{kept_image_concept}}', kept_image_concept)
  .replaceAll('{{buyer_stage}}', '#1')
  .replaceAll('{{buyer_objective}}', 'education')
  .replaceAll('{{caption_direction}}', '')
  .replaceAll('{{media_type}}', (post.media_type || 'image'))
  .replaceAll('{{image_concept}}', kept_image_concept)
  .replaceAll('{{video_concept}}', (post.video_concept || ''))
  .replaceAll('{{recommended_cta}}', 'soft: end with one engagement question')
  .replace(/\{\{[^}]+\}\}/g, '');
user = 'REGENERATION MODE. The previous draft was rejected.\n'
  + 'rejection_feedback: ' + rejection_feedback + '\n'
  + (kept_image_concept ? ('Keep the existing image; reuse this image_concept verbatim: ' + kept_image_concept + '\n') : '')
  + 'Previous post_body: ' + (post.post_body || '') + '\n'
  + 'Previous first_comment: ' + (post.first_comment || '') + '\n\n'
  + user;

// Visual variety for image regeneration: rotate the scene type by the post's date shifted
// by revision (so a rejected image moves to a NEW angle), resolve the image template with
// the rejection feedback, and remember recent image concepts to avoid repeats.
const VISUAL_ANGLES = [
  'extreme close-up of impact-glass or frame hardware detail — product macro, no people',
  'a beautiful Florida home exterior with new impact windows — curb appeal, golden-hour light',
  'a bright, light-filled interior room seen through large impact windows',
  'a happy homeowner or family moment at home — relaxed, confident, smiling',
  'an installer or craftsman fitting a window — skilled hands, pride in the work',
  'a dramatic storm sky over a Florida neighborhood — homes standing strong, no people',
  'a coastal Florida scene — palms, water, homes built for the climate',
  'macro of rain streaming down impact glass while the interior beyond stays warm and dry'
];
const SB = '__SUPABASE_URL__';
const KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
let recentRows = [];
try { recentRows = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_posts?select=image_concept&image_concept=not.is.null&order=created_at.desc&limit=8', headers: { apikey: KEY, Authorization: 'Bearer ' + KEY }, json: true }); } catch (e) {}
const recent_scenes = (recentRows || []).map(r => String(r.image_concept || '').slice(0, 140)).filter(Boolean).join(' ; ') || 'none yet';
const angleDay = post.scheduled_date ? Math.floor(Date.parse(post.scheduled_date + 'T12:00:00Z') / 86400000) : Math.floor(Date.now() / 86400000);
const visual_angle = VISUAL_ANGLES[(angleDay + (post.revision || 0) + 1) % VISUAL_ANGLES.length];
// {{image_concept}} stays for the image node ('Pick Image Concept' decides the concept).
const image_template = (byName['image'] || '')
  .replaceAll('{{visual_angle}}', visual_angle)
  .replaceAll('{{recent_scenes}}', recent_scenes)
  .replaceAll('{{image_feedback}}', regen_image ? rejection_feedback : 'none');

return [{ json: {
  system: byName['style_guide'] || '',
  user,
  component, regen_copy, regen_image, regen_video,
  post_id: post.id,
  image_concept: kept_image_concept || (post.image_concept || ''),
  image_status: post.image_status,
  post_image_url: post.image_url || '',
  video_concept: post.video_concept || '',
  visual_angle,
  image_template
} }];

// Tolerant JSON parse: strip ```json fences, then JSON.parse; on failure extract
// the first balanced {...}. Returns the regenerated object { post_body, first_comment, image_concept, ... }.
let t = $json.content?.[0]?.text || '';
t = t.replace(/```json|```/g, '').trim();
let out;
try { out = JSON.parse(t); } catch (e) {
  const m = t.match(/\{[\s\S]*\}/); out = m ? JSON.parse(m[0]) : {};
}
return [{ json: out }];

// Effective image concept for regeneration: prefer a freshly regenerated concept
// (component='both'), else fall back to the existing/kept concept. Also carry the post
// copy so the image template's {{post_body}} slot can be filled.
let concept = '';
try { concept = $('Parse Regen Copy').first().json.image_concept; } catch (e) {}
if (!concept) concept = $('Build Regen Context').first().json.image_concept || '';
let post_body = '';
try { post_body = $('Parse Regen Copy').first().json.post_body; } catch (e) {}
if (!post_body) post_body = $('Get Post').first().json.post_body || '';
return [{ json: { concept, post_body } }];

// Decode the base64 image returned by the provider and prepare it as binary for upload.
const b64 = $json.data?.[0]?.b64_json;
if (!b64) throw new Error('No image returned');
const path = `${$now.toFormat('yyyy-LL-dd')}-${Math.random().toString(36).slice(2,10)}.png`;
return [{ json: { path }, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), path, 'image/png') } }];

// Regenerate the video from the kept seed image + the post's video_concept via fal
// (Veo 3.1 image-to-video by default, swappable). Submit -> poll -> download the MP4, returned
// as binary for the Upload node. Throws (surfaced in the n8n log) when FAL_KEY is unset or the
// job fails/times out. Model: $env.FAL_ANIMATE_MODEL, else fb_settings.animate_still_model,
// else the veo3.1/fast default.
const FAL_KEY = $env.FAL_KEY;
if (!FAL_KEY) throw new Error('FAL_KEY is not set on this n8n instance');
const SB = '__SUPABASE_URL__';
const KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
let model = $env.FAL_ANIMATE_MODEL || '';
if (!model) {
  try {
    const rows = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_settings?id=eq.1&select=animate_still_model', headers: { apikey: KEY, Authorization: 'Bearer ' + KEY }, json: true });
    model = (rows && rows[0] && rows[0].animate_still_model) || '';
  } catch (e) {}
}
if (!model) model = 'fal-ai/veo3.1/fast/image-to-video';
const ctx = $('Build Regen Context').first().json;
const imageUrl = ctx.post_image_url;
const prompt = ctx.video_concept || 'Subtle, brand-safe motion: soft light shift and a slow push-in. No text, no logos.';
const fh = { Authorization: 'Key ' + FAL_KEY, 'Content-Type': 'application/json' };
const sub = await this.helpers.httpRequest({ method: 'POST', url: 'https://queue.fal.run/' + model, headers: fh, body: { prompt, image_url: imageUrl, aspect_ratio: '9:16', duration: '8s', resolution: '720p', generate_audio: false }, json: true });
if (!sub || !sub.status_url) throw new Error('fal submit failed: ' + JSON.stringify(sub));
let out = null;
for (let i = 0; i < 60; i++) {
  await new Promise(r => setTimeout(r, 5000));
  const st = await this.helpers.httpRequest({ method: 'GET', url: sub.status_url, headers: fh, json: true });
  const s = st && st.status;
  if (s === 'COMPLETED') { out = await this.helpers.httpRequest({ method: 'GET', url: sub.response_url, headers: fh, json: true }); break; }
  if (s === 'FAILED' || s === 'ERROR') throw new Error('fal video job failed: ' + JSON.stringify(st));
}
if (!out) throw new Error('fal video timed out after ~5 min');
const vurl = out.video && out.video.url;
if (!vurl) throw new Error('fal returned no video.url: ' + JSON.stringify(out));
const path = `${$now.toFormat('yyyy-LL-dd')}-${Math.random().toString(36).slice(2,10)}.mp4`;
const bin = await this.helpers.httpRequest({ method: 'GET', url: vurl, encoding: 'arraybuffer', returnFullResponse: false });
return [{ json: { path, video_url: SB + '/storage/v1/object/public/fb-videos/' + path }, binary: { data: await this.helpers.prepareBinaryData(Buffer.from(bin), path, 'video/mp4') } }];
